import { createClient } from 'supabase';
const html=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#07111f"><title>Football Intelligence</title><style>body{margin:0;background:#07111f;color:#eaf2ff;font-family:system-ui}.w{max-width:950px;margin:auto;padding:18px}.m,small{color:#8fa6c4}h1{margin:0;font-size:22px}h2{font-size:16px}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin:16px 0}.c,.p{background:#0e1b2d;border:1px solid #1c3554;border-radius:12px;padding:12px}.c b{display:block;font-size:20px;margin-top:4px}.g{color:#5ee6a8}.a{color:#ffd166}.pitch{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;background:#0d3228;border-radius:16px;padding:10px}.p span{display:block;font-size:10px;color:#86cab0}.p b{font-size:13px}.p small{display:block;font-size:10px}.bench{display:flex;gap:8px;overflow:auto}.bench .p{min-width:145px}table{width:100%;border-collapse:collapse;background:#0e1b2d;border-radius:12px;overflow:hidden;font-size:12px}th,td{padding:9px 6px;border-bottom:1px solid #182e49;text-align:right}th:nth-child(2),td:nth-child(2){text-align:left}.note{padding:10px;background:#302515;color:#ffd98c;border-radius:10px;font-size:11px}@media(min-width:700px){.cards{grid-template-columns:repeat(4,1fr)}.pitch{grid-template-columns:repeat(4,1fr)}}@media(max-width:520px){th:nth-child(5),td:nth-child(5),th:nth-child(7),td:nth-child(7){display:none}}</style></head><body><div class="w"><h1>Football Intelligence</h1><div class="m" id="sub">Loading…</div><div id="app">Loading model…</div></div><script>const A='https://knooiwezzsxcwhtjtdap.supabase.co/functions/v1/fpl-api',n=v=>Number(v||0),pct=v=>(100*n(v)).toFixed(1)+'%';function cs(a,k){const o=[];function r(s,p){if(p.length===k){o.push([...p]);return}for(let i=s;i<=a.length-(k-p.length);i++){p.push(a[i]);r(i+1,p);p.pop()}}r(0,[]);return o}function opt(s){const g=s.filter(x=>x.position==='GKP'),f=s.filter(x=>x.position!=='GKP');let b;for(const k of g)for(const c of cs(f,10)){const q=p=>c.filter(x=>x.position===p).length;if(q('DEF')<3||q('DEF')>5||q('MID')<2||q('MID')>5||q('FWD')<1||q('FWD')>3)continue;const xi=[k,...c],sc=xi.reduce((z,x)=>z+n(x.expected_points),0);if(!b||sc>b.sc)b={xi,sc}}const ids=new Set(b.xi.map(x=>x.id)),bn=s.filter(x=>!ids.has(x.id)),xp=[...b.xi].sort((a,b)=>n(b.expected_points)-n(a.expected_points)),tl=[...b.xi].sort((a,b)=>n(b.p_15_plus)-n(a.p_15_plus));const cap=xp.slice(0,5).sort((a,b)=>(n(b.expected_points)+5*n(b.p_15_plus)+8*n(b.p_20_plus))-(n(a.expected_points)+5*n(a.p_15_plus)+8*n(a.p_20_plus)))[0],vc=xp.filter(x=>x.id!==cap.id)[0];return{...b,bn,cap,vc,tl:tl[0]}}function pc(x,t=''){return '<div class="p"><span>'+t+'</span><b>'+x.name+'</b><small>'+n(x.expected_points).toFixed(2)+' xPts · '+pct(x.p_15_plus)+' 15+</small></div>'}(async()=>{try{const r=await fetch(A,{cache:'no-store'}),d=await r.json();if(!d.ok)throw Error(d.error);document.getElementById('sub').textContent='FPL Engine · v'+d.model_version+' · GW'+d.gameweek;const o=opt(d.squad),ord={GKP:0,DEF:1,MID:2,FWD:3};o.xi.sort((a,b)=>ord[a.position]-ord[b.position]);const rk=[...d.squad].sort((a,b)=>n(b.expected_points)-n(a.expected_points));document.getElementById('app').innerHTML='<div class="cards"><div class="c"><small>XI xPts</small><b>'+o.sc.toFixed(2)+'</b></div><div class="c"><small>Captain</small><b class="g">'+o.cap.name+'</b></div><div class="c"><small>Vice</small><b>'+o.vc.name+'</b></div><div class="c"><small>Top haul</small><b class="a">'+o.tl.name+'</b></div></div>'+(d.post_deadline_development_run?'<div class="note">GW1 is a post-deadline development run and excluded from predictive backtesting.</div>':'')+'<h2>Optimized XI</h2><div class="pitch">'+o.xi.map(x=>pc(x,x.position+(x.id===o.cap.id?' · C':'')+(x.id===o.vc.id?' · VC':''))).join('')+'</div><h2>Bench</h2><div class="bench">'+o.bn.sort((a,b)=>n(b.expected_points)-n(a.expected_points)).map((x,i)=>pc(x,x.position==='GKP'?'GK':'Bench '+(i+1))).join('')+'</div><h2>Full 15</h2><table><tr><th>#</th><th>Player</th><th>xMin</th><th>xPts</th><th>10+</th><th>15+</th><th>20+</th><th>DC</th></tr>'+rk.map((x,i)=>'<tr><td>'+(i+1)+'</td><td><b>'+x.name+'</b><small>'+x.team+' · '+x.position+'</small></td><td>'+n(x.expected_minutes).toFixed(0)+'</td><td><b>'+n(x.expected_points).toFixed(2)+'</b></td><td>'+pct(x.p_10_plus)+'</td><td>'+pct(x.p_15_plus)+'</td><td>'+pct(x.p_20_plus)+'</td><td>'+pct(x.p_dc)+'</td></tr>').join('')+'</table>'}catch(e){document.getElementById('app').textContent='Dashboard error: '+e.message}})();</script></body></html>`;
Deno.serve(async()=>{const ks=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}'),sb=createClient(Deno.env.get('SUPABASE_URL')!,ks.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}});let {error}=await sb.storage.createBucket('dashboard',{public:true,fileSizeLimit:'1MB'});if(error&&!String(error.message).toLowerCase().includes('already')) return Response.json({ok:false,error:error.message},{status:500});const up=await sb.storage.from('dashboard').upload('index.html',new Blob([html],{type:'text/html; charset=utf-8'}),{contentType:'text/html; charset=utf-8',upsert:true,cacheControl:'0'});if(up.error)return Response.json({ok:false,error:up.error.message},{status:500});const pub=sb.storage.from('dashboard').getPublicUrl('index.html');return Response.json({ok:true,url:pub.data.publicUrl});});
